        return event.GetJoystickButtonPressureFraction();
    if (event.GetType() == T_KP || event.GetType() == T_KH || event.GetType() == T_LP || event.GetType() == T_LH ||
        event.GetType() == T_MP || event.GetType() == T_MH || event.GetType() == T_RP || event.GetType() == T_RH ||
